fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of input rows
    let rows = x.len();
    // Number of input columns (all rows have the same length and x is non-empty)
    let cols = x[0].len();

    // Prepare the output with `cols` rows, each able to hold `rows` elements
    let mut result: Vec<Vec<f32>> = vec![Vec::with_capacity(rows); cols];

    // Consume each row of the input, pushing its elements into the proper output row
    for row in x {
        for (col_idx, value) in row.into_iter().enumerate() {
            result[col_idx].push(value);
        }
    }

    result
}

